const text = $input.first().json.output.html
const buffer = Buffer.from(text, 'utf8');
const binaryData = {
  data: buffer.toString('base64'),
  mimeType: 'application/octet-stream',
  fileName: '$input.first().json.output.title.html',
};
items[0].binary = { data: binaryData };
return items;

// Si tu binary se llama distinto a "data", cámbialo aquí
const binField = 'data';
const nombre_file= $input.first().json.output.title + '.pdf'

for (const item of items) {
  if (item.binary?.[binField]) {
    item.binary[binField].fileName = nombre_file;
    item.binary[binField].fileExtension = 'pdf';
    item.binary[binField].mimeType = 'application/pdf'; // opcional pero recomendable
  }
}
return items;
